import type { DefaultRawDatum } from "@harbor-charts/pie";
import {
	ResponsiveSunburst as Sunburst,
	type SunburstSvgProps,
} from "@harbor-charts/sunburst";
import { Component, Element, Host, Method, Prop, h } from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { sunburst } from "@harbor/chart-config/sunburst";

const { getSunburstBaseConfig } = sunburst;

import merge from "deepmerge";
import { browserDownloadCsv } from "../chart-board/board-util";
import {
	noopChartTooltip,
	omitChartConfigKeys,
} from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
import { hideSunburstTooltip, showSunburstTooltip } from "./chart-util";

type SunburstChartConfig = Omit<
	Partial<SunburstSvgProps<DefaultRawDatum>>,
	"tooltip"
> & {
	itemTooltip?: (data, event, h) => string | object | false;
	onFocus?: (data, event) => void;
	onBlur?: (data, event) => void;
	isFocusable?: boolean;
};

type ConfigWithNivoTooltip = SunburstChartConfig & { tooltip?: unknown };

/**
 * @since 2.11.4
 * @status beta
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 */
@Component({
	tag: "hbr-sunburst-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrSunburstChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;
	virtualElement: HTMLElement;

	/** Chart configuration object. Refer to https://nivo.rocks/sunburst */
	@Prop({ mutable: true }) config: SunburstChartConfig;
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";

	/** Chart loading flag */
	@Prop() loading = false;

	/** Chart header from magnetic design */
	@Prop()
	showHeader: "all" | "title" | "action" | "none" = "none";

	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: SunburstChartConfig,
		createElement: typeof React.createElement,
		util: typeof sunburst,
	) => ConfigWithNivoTooltip;

	/** Default popover props. Set `selfManaged` to let the popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrSunburstElement;

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(filename = "Export.csv", customFunc?: (data) => void) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(this.convertToCSV(), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;
	private warnedAboutNivoTooltip = false;

	private isPopoverSelfManaged() {
		return isChartPopoverSelfManaged(true, this.popoverOptions);
	}

	componentDidLoad() {
		this.renderChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		return this.renderChart();
	}

	renderChart = async () => {
		const configWithNivoTooltip = this.config as ConfigWithNivoTooltip;
		if (
			!this.warnedAboutNivoTooltip &&
			configWithNivoTooltip.tooltip !== undefined
		) {
			console.warn(
				"hbr-sunburst-chart: config.tooltip is not supported. Use itemTooltip instead.",
			);
			this.warnedAboutNivoTooltip = true;
		}
		const publicConfig = omitChartConfigKeys(configWithNivoTooltip, [
			"tooltip",
		]) as SunburstChartConfig;
		const baseConfig = getSunburstBaseConfig({
			itemsEventHandlers: {
				onFocus: (data, event) => {
					showSunburstTooltip(data, event, this.tooltipRef, publicConfig);
					this.config.onFocus?.(data, event);
				},
				onBlur: (data, event) => {
					hideSunburstTooltip(this.tooltipRef);
					this.config.onBlur?.(data, event);
				},
				onClick: (data, event) => {
					this.config.onClick?.(data, event);
				},

				onMouseEnter: (data, event) => {
					showSunburstTooltip(data, event, this.tooltipRef, publicConfig);
					this.config.onMouseEnter?.(data, event);
				},
				onMouseLeave: (data, event) => {
					if (!this.isPopoverSelfManaged()) {
						hideSunburstTooltip(this.tooltipRef);
					}
					this.config.onMouseLeave?.(data, event);
				},
			},
		});

		const existingEventHandlers = {
			onMouseEnter: baseConfig.onMouseEnter,
			onMouseLeave: baseConfig.onMouseLeave,
			onClick: baseConfig.onClick,
			onblur: baseConfig.onBlur,
			onFocus: baseConfig.onFocus,
		};

		let fullConfig = merge(baseConfig, publicConfig) as SunburstChartConfig;

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as Partial<SunburstSvgProps<DefaultRawDatum>>;
		fullConfig = omitChartConfigKeys(fullConfig, [
			"tooltip",
		]) as SunburstChartConfig;
		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(
				fullConfig,
				React.createElement,
				sunburst,
			);
		}
		fullConfig = {
			...fullConfig,
			tooltip:
				(fullConfig as ConfigWithNivoTooltip).tooltip ?? noopChartTooltip,
		} as ConfigWithNivoTooltip;
		if (!this.chartRef.innerHTML.length) {
			const newRoot = createRoot(this.chartRef);
			newRoot.render(
				React.createElement(
					Sunburst,
					fullConfig as SunburstSvgProps<DefaultRawDatum>,
					null,
				),
			);
			this.contextRoot = newRoot;
		} else {
			this.contextRoot.render(
				React.createElement(
					Sunburst,
					fullConfig as SunburstSvgProps<DefaultRawDatum>,
					null,
				),
			);
		}

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}
	};

	convertToCSV() {
		// no default way of converting to csv for multiple levels
		return "";
	}

	render() {
		const { config } = this;
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const popoverOptions = resolveChartPopoverOptions(
			{ distance: 10, variant: "chart" },
			this.popoverOptions,
			true,
		);

		return (
			<Host>
				<hbr-chart-board
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={Object.keys(config.data).length === 0}
					style={{ width: this.width, height: this.height }}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					<div slot="header" part="header" class="chart-sunburst__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class={`--hbr-sunburst --sunburst-chart ${
							this.config?.isInteractive === false ? "non-interactive" : ""
						} ${this.config?.isFocusable === false ? "non-focusable" : ""}
            `}
						part="chart"
					/>
					<slot name="footer" />
					<slot slot="loading-state" name="loading-state" />
					<slot slot="empty-state" name="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
